    const hin = Math.min(feather * 0.5, 0.5), hout = feather - hin;
    for (let i = 0; i < n; i++) { IX[i] = p[i * 2] - NX[i] * hin; IY[i] = p[i * 2 + 1] - NY[i] * hin; }
    const C = (i) => (per ? col[i] : col);
