                const u = j / COLS, id = V.length / 3;
                V.push(V[r * 3], V[r * 3 + 1] + (V[l * 3 + 1] - V[r * 3 + 1]) * u, V[r * 3 + 2] + (V[l * 3 + 2] - V[r * 3 + 2]) * u); NN.push(dir, 0, 0);
