        const H2 = 0.86 * k, rows = 20, cr = Math.cos(recline), sr2 = Math.sin(recline);
        const width = (t) => (0.235 + 0.04 * ss(0.20, 0.55, t) - 0.145 * ss(0.58, 0.72, t) + 0.01 * ss(0.75, 0.9, t)) * k;
        const bolster = (t) => 0.13 - 0.08 * ss(0.52, 0.70, t);
