        this.af = -(Math.atan2(vy + this.a * s.yawRate, Math.abs(vx)) - d) * R2D;
        this.ar = -Math.atan2(vy - this.b * s.yawRate, Math.abs(vx)) * R2D;
        this.peakAngle = Math.max(this.peakAngle * Math.exp(-dt * 0.25), Math.abs(beta));
